const defaultDescription = 'Pour Decisions is een whiskyclub: proeverijen, whiskyreizen en alles over landen, regio\'s, distilleries en whisky\'s. Slechte beslissingen. Goede whisky.';

interface PageSeoOptions {
  title: string;
  description?: string;
  image?: string;
  /** Overrides from the CMS (seoTitle, seoDescription, ogImage). */
  seo?: Seo;
}

export function usePageSeo({ title, description, image, seo }: PageSeoOptions) {
  const route = useRoute();
  const siteUrl = useSiteConfig().url;
  const pageTitle = seo?.seoTitle || title;
  const pageDescription = seo?.seoDescription || description || defaultDescription;
  const ogImage = seo?.ogImage || image;
  const url = `${siteUrl}${route.path}`;

  useSeoMeta({
    title: pageTitle,
    description: pageDescription,
    ogTitle: pageTitle,
    ogDescription: pageDescription,
    ogType: 'website',
    ogUrl: url,
    ogLocale: 'nl_NL',
    ogSiteName: 'Pour Decisions',
    ogImage,
    twitterCard: ogImage ? 'summary_large_image' : 'summary',
  });
  useHead({ link: [{ rel: 'canonical', href: url }] });
}
